		BlockKind:     template.BlockKindExtractor,
		Values:        map[string]any{"appId": "order-extractor", "topic": "orders"}, // no contract
	})
	if err != nil {
		t.Fatal(err)
	}

	_, _, err = runCreate(t, srv, CreateOptions{Name: "OrderFlow", StartDir: ws, Version: "v1"})
