		t.Fatal(err)
	}
	var cs strings.Builder
	if err := ct.Execute(&cs, values); err != nil {
		t.Fatal(err)
	}
	if cs.String() != "Order" {
		t.Errorf("dependency contract = %q, want Order", cs.String())
